use anyhow::{Context, Result};
use colored::Colorize;
use git2::Repository;
use std::fs::{self, OpenOptions};
use std::io::Write;
#[cfg(unix)]
use std::os::unix::fs::{OpenOptionsExt, PermissionsExt};
use std::path::Path;
use std::process::Command;

const HOOK_SCRIPT: &str = r#"#!/bin/sh
# veil-rs pre-commit hook
# Generated by `veil pre-commit init`

veil scan --staged --fail-on-findings 1 --mask-mode redact --no-color
status=$?
case "$status" in
    0) exit 0 ;;
    1)
        printf '%s\n' 'Veil: commit blocked by findings. Review them locally before committing.' >&2
        exit 1
        ;;
    *)
        printf 'Veil: scan failed (exit %s). Commit blocked; resolve the scan error first.\n' "$status" >&2
        exit 2
        ;;
esac
"#;

pub fn init() -> Result<()> {
    let repo = Repository::open_from_env().context("Cannot open Git repository")?;
    let root = repo
        .workdir()
        .context("Hook installation requires a Git working tree")?;
    // Ask Git so linked worktrees and effective global/local core.hooksPath agree.
    let output = Command::new("git")
        .current_dir(root)
        .args(["rev-parse", "--path-format=absolute", "--git-path", "hooks"])
        .output()
        .context("Cannot resolve Git hooks directory")?;
    anyhow::ensure!(
        output.status.success(),
        "Cannot resolve Git hooks directory"
    );
    let path = String::from_utf8(output.stdout).context("Git hooks path must be UTF-8")?;
    let path = path.strip_suffix('\n').unwrap_or(&path);
    anyhow::ensure!(!path.contains('\n'), "Git hooks path must be a single line");
    let hooks_dir = Path::new(path);
    anyhow::ensure!(hooks_dir.is_absolute(), "Git hooks path must be absolute");
    fs::create_dir_all(hooks_dir).context("Cannot create Git hooks directory")?;
    let hook_path = hooks_dir.join("pre-commit");
    let mut options = OpenOptions::new();
    options.write(true).create_new(true);
    #[cfg(unix)]
    options.mode(0o600);
    // Exclusive creation refuses regular files, directories and even broken symlinks.
    // No existing check is moved, replaced, or disabled; configuration stays intact.
    let mut hook = options.open(&hook_path).with_context(|| {
        format!(
            "Cannot create hook at {}. Existing hooks are never replaced. Integrate `veil scan --staged --fail-on-findings 1 --mask-mode redact --no-color` into the existing hook instead",
            hook_path.display()
        )
    })?;
    hook.write_all(HOOK_SCRIPT.as_bytes())
        .context("Cannot write Git hook")?;
    hook.sync_all().context("Cannot sync Git hook")?;
    #[cfg(unix)]
    hook.set_permissions(fs::Permissions::from_mode(0o755))
        .context("Cannot make Git hook executable")?;
    println!(
        "{} Veil pre-commit hook installed successfully!",
        "✅".green()
    );
    println!("   The hook is located at: {}", hook_path.display());
    Ok(())
}
